import { Scene, Spline, CurveType, Vec3, Color } from "retiam";

const scene = new Scene({ canvas });

const points = [
    new Vec3(-8, -2, 0),
    new Vec3(-4, 3, 0),
    new Vec3(0, -1, 0),
    new Vec3(4, 4, 0),
    new Vec3(8, -2, 0)
];

// 1. Natural C² Spline
const naturalSpline = new Spline(points, {
    type: CurveType.Natural,
    stroke: Color.fromHex("#38bdf8"),
    stroke_width: 0.12,
    segments: 30
});
scene.add(naturalSpline);

// 2. Closed B-Spline loop
const bSpline = new Spline(points, {
    type: CurveType.BSpline,
    degree: 3,
    closed: true,
    stroke: Color.fromHex("#f43f5e"),
    stroke_width: 0.08
});
scene.add(bSpline);

// 3. Dynamic per-frame control point oscillation
scene.always(({ time }) => {
    points[2].y = Math.sin(time * 3.0) * 2.5;
    naturalSpline.setPoints(points);
});
